pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Make the test contract itself the initial owner so onlyOwner can be satisfied.
        // By default, C.owner() == address(0). We need a non-zero owner to call transferOwnership.
        // The constructor does not set owner, so we set it here using a low-level call to a public function that might be missing.
        // C has no init, so we use the fact that owner is public and can be written via the setter? No setter exists.
        // But transerOwnership is onlyOwner; we need to be the owner first.
        // Since constructor leaves owner == address(0), msg.sender == owner means only address(0) can call. That's impossible.
        // To allow testing, we deploy C, then the test contract pranks as address(0)? But tx.origin? Not needed.
        // We use vm.startPrank to set the initial owner via a workaround: the contract C does not expose a way to set owner except through transferOwnership which needs an owner.
        // Therefore we must first set the owner slot directly? That would be vm.store, which is REJECTED.
        // So we use a different approach: we deploy a helper that becomes the initial owner, but C constructor is empty.
        // To make C have a non-zero owner, we can exploit that the test contract itself can be the deployer and C's constructor does not set owner.
        // But the rule says: you must drive C through transferOwnership. To call transferOwnership, msg.sender must be owner.
        // Since owner is 0 initially, only address(0) can call transferOwnership. The fuzzer can give address(0) as actor?
        // Yes, we can prank as address(0). That's allowed.
    }

    function testFuzz_property(address currentOwner, address newOwner) public {
        // The initial owner is address(0). We prank as address(0) to call transferOwnership first to set currentOwner.
        // But to test the property after a transfer by the current owner, we need to set the owner to currentOwner first.
        // We can prank as address(0) and call transferOwnership(currentOwner) to set owner = currentOwner.
        // Then we can prank as currentOwner to call transferOwnership(newOwner) and check the result.
        // This assumes currentOwner != address(0) to avoid confusion with initial zero address.
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(currentOwner != newOwner);

        // Step 1: Set the owner to currentOwner. Only address(0) can call initially.
        vm.prank(address(0));
        c.transferOwnership(currentOwner);

        // Step 2: Now currentOwner transfers ownership to newOwner.
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // After the transfer, the owner must equal newOwner.
        assertEq(c.owner(), newOwner);
    }
}

