pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner, bool isCurrentOwner) public {
        // 1. Admissible domain: keep all addresses (except zero if needed) and decide scenario by isCurrentOwner bool
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Remember current owner before the call
        address originalOwner = c.owner();

        // Set up caller: if isCurrentOwner, make caller the current owner; else caller is a random non-owner
        if (isCurrentOwner) {
            // become originalOwner to make caller the current owner
            vm.prank(originalOwner);
            c.transferOwnership(caller);
        }

        // 2. Drive the call: caller attempts to transfer ownership to newOwner
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // 3. Assertion: owner changes only if caller is the current owner before the call.
        // The reference C (with onlyOwner) ensures only current owner can change owner;
        // the buggy version allows anyone to change it, violating this rule when caller is not owner.
        bool ownerChanged = (c.owner() != originalOwner);
        assertTrue(ownerChanged == isCurrentOwner);
    }
}

