pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner, bool callerIsOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        if (callerIsOwner) {
            vm.prank(c.owner());
            c.transferOwnership(caller);
        }
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        if (caller == c.owner()) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}

