        vm.assume(caller != address(0));
        vm.assume(_newOwner != address(0));
        address original_owner = c.owner();
        bool caller_is_owner = (caller == original_owner);
        if (prankCaller) {
            vm.prank(caller);
        }
        c.transferOwnership(_newOwner);
        address final_owner = c.owner();
        assertTrue(caller_is_owner || final_owner == original_owner);
    }
}

